export type WherryPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function wherryProgram(
  config: { programAddress?: Address | HasAddress } = {}
) {
  return <T extends WherryPluginRequirements>(
    client: T
  ): ExtendedClient<T, { wherry: WherryPlugin }> => {
    return extendClient(client, {
      wherry: {
        accounts: {
          gameConfig: addSelfFetchFunctions(client, getGameConfigCodec()),
          payerRecord: addSelfFetchFunctions(client, getPayerRecordCodec()),
          tab: addSelfFetchFunctions(client, getTabCodec()),
        },
        instructions: {
          closeTab: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseTabInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          commitSeed: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCommitSeedInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          openTab: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenTabInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          revealSeed: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevealSeedInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          settle: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          settleViaCourier: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleViaCourierInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          topUp: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getTopUpInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
        },
        pdas: {
          payerRecord: (seeds, pdaConfig) =>
            findPayerRecordPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          game: (seeds, pdaConfig) =>
            findGamePda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          tab: (seeds, pdaConfig) =>
            findTabPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
        },
        identifyAccount: identifyWherryAccount,
        identifyInstruction: identifyWherryInstruction,
        parseInstruction: parseWherryInstruction,
      } as WherryPlugin,
    });
  };
}
